SECTION_KINDS: Final[frozenset[str]] = frozenset(s.kind for s in SECTIONS)


async def execute(
    conn: AsyncConnection,
    sections: Sequence[str] | None = None,
    exclude_sections: Sequence[str] | None = None,
    idempotent: bool = True,
    dry_run: bool = False,
    extension_stubs: dict[str, str] | None = None,
) -> ExecutionResult:
    """Execute DDL sections.

    Two-phase execution: transactional sections run inside a single
    transaction, non-transactional sections run outside afterward.

    Ops with idempotent_sql=None are inherently re-runnable statements
    (COMMENT ON, SET STATISTICS, OWNER TO, ENABLE/FORCE ROW LEVEL SECURITY,
    partman config UPDATE); for those, executing op.sql again is harmless,
    so idempotent=True falls back to op.sql. Exception: partman
    create_parent has no idempotent form and errors if re-run.
    """
    if sections is not None and exclude_sections is not None:
        raise ValueError("Cannot specify both sections and exclude_sections")
    if sections is not None:
        unknown = set(sections) - SECTION_KINDS
        if unknown:
            raise ValueError(f"Unknown section(s): {sorted(unknown)}. Valid: {sorted(SECTION_KINDS)}")
    if exclude_sections is not None:
        unknown = set(exclude_sections) - SECTION_KINDS
        if unknown:
            raise ValueError(f"Unknown section(s): {sorted(unknown)}. Valid: {sorted(SECTION_KINDS)}")
    result = ExecutionResult()
    selected = [s for s in SECTIONS if (sections is None or s.kind in sections) and (exclude_sections is None or s.kind not in exclude_sections)]
    transactional = [s for s in selected if s.transactional]
    non_transactional = [s for s in selected if not s.transactional]

    # Phase 1: transactional ops in a single transaction.
    if transactional and not dry_run:
        async with conn.transaction() as tx:
            for sec in transactional:
                for op in sec.ops:
                    # idempotent_sql=None means op.sql is inherently re-runnable.
                    stmt = op.idempotent_sql if idempotent and op.idempotent_sql else op.sql
                    if extension_stubs is not None and sec.kind == "extensions" and op.name in extension_stubs:
                        stmt = extension_stubs[op.name]
                    try:
                        await tx.execute(stmt)
                        result.executed.append((sec.kind, op.name))
                    except Exception as e:
                        result.errors.append((sec.kind, op.name, str(e)))
                        raise
    elif transactional and dry_run:
        for sec in transactional:
            for op in sec.ops:
                result.executed.append((sec.kind, op.name))

    # Phase 2: non-transactional ops outside any transaction.
    for sec in non_transactional:
        for op in sec.ops:
            # idempotent_sql=None means op.sql is inherently re-runnable.
            stmt = op.idempotent_sql if idempotent and op.idempotent_sql else op.sql
            if extension_stubs is not None and sec.kind == "extensions" and op.name in extension_stubs:
                stmt = extension_stubs[op.name]
            if not dry_run:
                try:
                    await conn.execute(stmt)
                    result.executed.append((sec.kind, op.name))
                except Exception as e:
                    result.errors.append((sec.kind, op.name, str(e)))
            else:
                result.executed.append((sec.kind, op.name))

    return result


async def verify(
    conn: AsyncConnection,
    sections: Sequence[str] | None = None,
    exclude_sections: Sequence[str] | None = None,
) -> VerifyResult:
    """Check which ops across selected sections exist in the database."""
    if sections is not None and exclude_sections is not None:
        raise ValueError("Cannot specify both sections and exclude_sections")
    if sections is not None:
        unknown = set(sections) - SECTION_KINDS
        if unknown:
            raise ValueError(f"Unknown section(s): {sorted(unknown)}. Valid: {sorted(SECTION_KINDS)}")
    if exclude_sections is not None:
        unknown = set(exclude_sections) - SECTION_KINDS
        if unknown:
            raise ValueError(f"Unknown section(s): {sorted(unknown)}. Valid: {sorted(SECTION_KINDS)}")
    result = VerifyResult()
    selected = [s for s in SECTIONS if (sections is None or s.kind in sections) and (exclude_sections is None or s.kind not in exclude_sections)]
    for sec in selected:
        for op in sec.ops:
            if await sec.exists(conn, op):
                result.present.append((sec.kind, op.name))
            else:
                result.missing.append((sec.kind, op.name))
    return result


async def create_schema(conn: AsyncConnection) -> ExecutionResult:
    """Execute all DDL, failing on conflicts."""
    return await execute(conn, idempotent=False)


async def ensure_schema(conn: AsyncConnection) -> ExecutionResult:
    """Execute all DDL idempotently, safe to run on existing databases."""
    return await execute(conn, idempotent=True)
